/* The actual broker, security workers, persistence and Web executable run here.
 * Only UART/time/network observation and panel input are fake. */
#define _GNU_SOURCE
#define WEB_INTEGRATION_FIXTURE
#include "../app/test_gateway_application_network.c"
#include "web/web_gateway.h"
#include <stdlib.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/stat.h>
#include <unistd.h>
static int stopping;
static void stopped(int n){(void)n;stopping=1;}
static gateway_config_result_t disk_stage(void *x,const char *d,const gateway_persistent_config_t *c){(void)x;return gateway_config_stage(d,c,GATEWAY_SAVE_FAIL_NONE);}
static gateway_config_result_t disk_promote(void *x,const char *d){(void)x;return gateway_config_promote(d,GATEWAY_SAVE_FAIL_NONE);}
static void disk_discard(void *x,const char *d){(void)x;gateway_config_discard_staged(d);}
int main(int argc,char **argv){fixture_t f;web_gateway_t w;gateway_panel_t panel;char sec[512],display[512],command[512],buffer[32],last[13]="";size_t n;unsigned int i,offset=0,ip_offset=0,ticks=0;gateway_persistent_config_t c;gateway_config_source_t source;
 if(argc!=3)return 2;signal(SIGTERM,stopped);signal(SIGINT,stopped);mkdir(argv[1],0700);snprintf(sec,sizeof(sec),"%s/security",argv[1]);snprintf(display,sizeof(display),"%s/display",argv[1]);snprintf(command,sizeof(command),"%s/local-command",argv[1]);use_full=use_service=1;setup(&f);if(gateway_config_startup_select(argv[1],&c,&source)==GATEWAY_CONFIG_OK)f.config=c;f.dependencies.configuration_directory=argv[1];gateway_application_request_stop(&f.application);step_to_stop(&f);gateway_application_init(&f.application,&f.dependencies);f.application.dependencies.configuration_directory=argv[1];f.application.dependencies.stage_configuration=disk_stage;f.application.dependencies.promote_configuration=disk_promote;f.application.dependencies.discard_configuration=disk_discard;step_to_runtime(&f);f.application.time.trust=GATEWAY_TIME_MANUAL;
 gateway_panel_init(&panel,&panel_ops,0);gateway_panel_step(&panel,&f.application);
 if(web_gateway_init(&w,&f.application,sec,argv[2],getenv("WEB_FIXTURE_HTTPS")?(unsigned int)atoi(getenv("WEB_FIXTURE_HTTPS")):18443U,getenv("WEB_FIXTURE_HTTP")?(unsigned int)atoi(getenv("WEB_FIXTURE_HTTP")):18080U))return 3;
 while(!stopping){ticks++;f.now=web_now();f.now+=offset;kernel->now=f.now;gateway_application_step(&f.application);for(i=0;i<2;++i){strcpy(w.test_addresses[i],i?"127.0.0.2":ip_offset?"127.0.0.3":"127.0.0.1");}
  if(!web_read_file(command,buffer,sizeof(buffer),&n)){unlink(command);if(!strcmp(buffer,"enable")||!strcmp(buffer,"disable")){if(f.application.coordinator.selected.settings.web_enabled!=(unsigned int)!strcmp(buffer,"enable")){panel.view=GATEWAY_PANEL_SYSTEM;panel.system_page=3;press(&panel,&f,GATEWAY_PANEL_KEY_F3);press(&panel,&f,GATEWAY_PANEL_KEY_F3);}}else if(!strcmp(buffer,"http")||!strcmp(buffer,"https")){c=f.application.coordinator.selected;c.schema_version=3;c.settings.web_protocol=!strcmp(buffer,"https");gateway_application_request_configuration(&f.application,&c);}else if(!strcmp(buffer,"both")){c=f.application.coordinator.selected;c.schema_version=3;c.settings.web_interface=2;gateway_application_request_configuration(&f.application,&c);}else if(!strcmp(buffer,"untrusted"))f.application.time.trust=GATEWAY_TIME_UNSYNCED;else if(!strcmp(buffer,"trusted"))f.application.time.trust=GATEWAY_TIME_MANUAL;else if(!strcmp(buffer,"panel-home"))panel.view=GATEWAY_PANEL_HOME;else if(!strcmp(buffer,"confirm-recovery"))press(&panel,&f,GATEWAY_PANEL_KEY_F3);else if(!strcmp(buffer,"cancel-recovery"))press(&panel,&f,GATEWAY_PANEL_KEY_F1);else if(!strcmp(buffer,"code"))web_gateway_local(&w,1);else if(!strcmp(buffer,"recover"))web_gateway_local(&w,2);else if(!strcmp(buffer,"cancel"))web_gateway_local(&w,0);else if(!strcmp(buffer,"stop-web-fixture")){if(w.pid>0)kill(w.pid,SIGSTOP);}else if(!strcmp(buffer,"rng-drain")){unsigned char scratch[32];unsigned int j;for(j=0;j<32;j++)if(web_random(scratch,sizeof(scratch)))break;web_clear(scratch,sizeof(scratch));}else if(!strcmp(buffer,"port-status")){char state[512];unsigned int starts=0,stops=0,active=0;for(i=0;i<GATEWAY_PORT_COUNT;i++){starts+=f.transport[i].starts;stops+=f.transport[i].stops;active+=f.transport[i].active!=0;}snprintf(sec,sizeof(sec),"%s/port-state",argv[1]);snprintf(state,sizeof(state),"{\"starts\":%u,\"stops\":%u,\"active\":%u}",starts,stops,active);web_atomic_file(sec,state,strlen(state));}else if(!strcmp(buffer,"status")){char state[256];snprintf(sec,sizeof(sec),"%s/web-state",argv[1]);snprintf(state,sizeof(state),"{\"state\":%u,\"error\":%u,\"saved\":%u,\"gateway\":%u,\"rng_pid\":%d,\"ticks\":%u,\"protocol\":%u,\"switch_pending\":%u}",f.application.web.state,f.application.web.error,f.application.coordinator.selected.settings.web_enabled,(unsigned)f.application.process_state,w.rng_pid,ticks,f.application.coordinator.selected.settings.web_protocol,w.switch_pending);web_atomic_file(sec,state,strlen(state));}else if(!strcmp(buffer,"draft-open")){panel.view=GATEWAY_PANEL_MENU;panel.selected=2;press(&panel,&f,GATEWAY_PANEL_KEY_F3);panel.candidate.ports[0].endpoint_port=1602;++panel.candidate.ports[0].revision;}else if(!strcmp(buffer,"draft-save")){panel.view=GATEWAY_PANEL_APPLY_CONFIRM;press(&panel,&f,GATEWAY_PANEL_KEY_F3);snprintf(sec,sizeof(sec),"%s/panel-result",argv[1]);web_atomic_file(sec,panel.local_validation_failed?"conflict":"accepted",8);}else if(!strcmp(buffer,"timeout"))offset+=70000;else if(!strcmp(buffer,"rebind"))ip_offset=!ip_offset;else if(!strcmp(buffer,"panel-save"))gateway_application_backlight_set(&f.application,!f.application.coordinator.selected.settings.backlight_on);}
  web_gateway_step(&w);gateway_panel_step(&panel,&f.application);if(strcmp(last,f.application.web.code)){strcpy(last,f.application.web.code);web_atomic_file(display,last,strlen(last));}usleep(1000);
 }
 web_gateway_close(&w);cleanup(&f);return failed?1:0;}
